// =============================================================
// 1. GLOBAL SHARED STATE (Telemetry & Flags)
// =============================================================
struct SystemState {
    // Sensor Data
    float v1 = 0, i1 = 0, w1 = 0, e1 = 0;
    float v2 = 0, i2 = 0, w2 = 0, e2 = 0;
    float freq1=50.0, pf1=1.0; 
    float freq2=50.0, pf2=1.0;

    // Connectivity
    bool wifiConnected = false;     
    bool internetAvailable = false; 
    bool internetRecovered = false; 
    bool serviceLocked = false;     
    bool radioDead = false;         
    bool apMode = false;            

    // Telemetry (Console & Dashboard)
    String wifiStateLabel = "BOOT";
    int wifiRssi = 0;
    String lastConnectAttempt = "N/A";
    bool pingSuccess = false;

    int syncSuccessCount = 0;
    int syncFailCount = 0;
    int lastHttpCode = 0;
    String lastSyncTime = "Never"; 
    String batchName = "None";
    String syncStateLabel = "IDLE";

    String sensorStatus = "INIT";
    String lastSensorRead = "N/A"; // [FIX] Restored variable
    String voltageStatus = "CHECK";
    int activeSensors = 0;

    // System
    DeviceState deviceState = DEVICE_BOOT;
    bool rtcValid = false;
    unsigned long lastNtpSync = 0; 
    int bufferCount = 0; 
    bool rebootRequired = false; 
    bool otaActive = false; 
    volatile bool isSyncing = false; 
    String rebootReason = "Unknown";
    String lastBootTime = "N/A";       
    String lastBootReasonLog = "N/A"; 
    int bootCount = 0; 
    int cpuLoad = 0;

    // Logging
    String logs[35];
    int logIdx = 0;

    void log(String msg) {
        Serial.println(msg);
        String ts = (rtcValid) ? rtc.now().timestamp(DateTime::TIMESTAMP_TIME) : String(millis()/1000);
        logs[logIdx] = "[" + ts + "] " + msg;
        logIdx = (logIdx + 1) % 35;
    }

    String getHealthStatus() {
        unsigned long sec = millis() / 1000;
        int d = sec / 86400; int h = (sec % 86400) / 3600; int m = (sec % 3600) / 60;
        String s = "Net:" + wifiStateLabel;
        s += " | Buf:" + String(bufferCount);
        s += " | Heap:" + String(ESP.getFreeHeap()/1024) + "k";
        s += " | Up:" + String(d) + "d:" + String(h) + "h:" + String(m) + "m";
        return s;
    }
} Sys;

