// --- 3.1 Time Manager ---
class TimeManager : public Process {
    unsigned long lastNtpCheck = 0;
    const char* ntpServers[3] = {"pool.ntp.org", "time.nist.gov", "time.google.com"};
    bool bootSyncDone = false;

    public:
    void setup() override {
        Sys.log("[Time] Init RTC...");
        if (!rtc.begin()) Sys.log("❌ RTC Failed");
        else { if (rtc.now().year() >= 2025) Sys.rtcValid = true; }
    }

    void update() override {
        if (Sys.deviceState == DEVICE_ONLINE) {
            if (!bootSyncDone || !Sys.rtcValid || (millis() - lastNtpCheck > 3600000)) { 
                performNtpSync();
                lastNtpCheck = millis();
            }
        }
    }

    void performNtpSync() {
        if (!bootSyncDone) Sys.log("⏳ Time Sync Initiated...");
        configTime(19800, 0, ntpServers[0], ntpServers[1], ntpServers[2]); 
        struct tm t;
        if (getLocalTime(&t, 10000)) { 
            rtc.adjust(DateTime(t.tm_year+1900, t.tm_mon+1, t.tm_mday, t.tm_hour, t.tm_min, t.tm_sec));
            Sys.rtcValid = true;
            Sys.lastNtpSync = millis();
            bootSyncDone = true;
            Sys.log("✅ NTP Synced: " + rtc.now().timestamp());
        } else {
            Sys.log("❌ NTP Sync Failed");
        }
    }
    bool isHealthy() override { return true; } 
    String getName() override { return "TimeMgr"; }
};

// --- 3.2 Sensor Manager ---
class SensorManager : public Process {
    unsigned long lastRead = 0;
    // [REMOVED] Sim Mode Flag
    float lastF1 = 50.0, lastPF1 = 1.0;
    float lastF2 = 50.0, lastPF2 = 1.0;
    int err1 = 0, err2 = 0;

    public:
    void setup() override { Sys.log("[Sensors] PZEMs Ready"); }

    void update() override {
        // 5-Second Polling Rate
        if (millis() - lastRead < 5000) return; 
        lastRead = millis();

        // Update Telemetry (Time Only)
        Sys.lastSensorRead = (Sys.rtcValid) ? rtc.now().timestamp(DateTime::TIMESTAMP_TIME) : String(millis()/1000);

        // [CLEANED] Direct Hardware Read Logic (Sim Mode Removed)
        readPZEM(pzem1, Sys.v1, Sys.i1, Sys.w1, Sys.e1, Sys.freq1, Sys.pf1, lastF1, lastPF1, err1);
        delay(50); 
        readPZEM(pzem2, Sys.v2, Sys.i2, Sys.w2, Sys.e2, Sys.freq2, Sys.pf2, lastF2, lastPF2, err2);

        // Update Status Flags
        if (err1 > 0 || err2 > 0) Sys.sensorStatus = "READ ERR";
        else Sys.sensorStatus = "OK";

        Sys.activeSensors = (Sys.v1 > 0 ? 1 : 0) + (Sys.v2 > 0 ? 1 : 0);
        Sys.voltageStatus = (Sys.v1 > 180 && Sys.v2 > 180) ? "✅ OK" : "⚠️ LOW";
    }

    // [REMOVED] toggleSim() function deleted

    void resetEnergy() { pzem1.resetEnergy(); pzem2.resetEnergy(); Sys.e1=0; Sys.e2=0; }
    bool isHealthy() override { return true; } 
    String getName() override { return "SensorMgr"; }

    private:
    void readPZEM(PZEM004Tv30 &pz, float &v, float &i, float &w, float &e, float &f, float &pf, 
              float &lf, float &lpf, int &err) {
        float rv = pz.voltage(); float ri = pz.current(); float rw = pz.power();
        float re = pz.energy(); float rf = pz.frequency(); float rpf = pz.pf();

        int bad = 0;
        if (isnan(rv) || rv < 0 || rv > 300.0) bad++; 
        if (isnan(ri) || ri < 0 || ri > 100) bad++;
        if (isnan(rw) || rw < 0 || rw > 30000) bad++;
        if (isnan(re)) bad++;

        // [FIX] ROOT CAUSE: If Voltage is NaN or <150V, force 0 immediately.
        // This prevents NaN from contaminating SystemState.
        if (isnan(rv) || rv < 150.0 || bad >= 3) { 
            err++; v = 0; i = 0; w = 0; f = 0; pf = 0; 
        } else {
            err = 0; v = rv; i = ri; w = rw; e = re;
            if (!isnan(rf) && rf >= 40 && rf <= 70) { f = rf; lf = rf; } else f = lf;
            if (!isnan(rpf) && rpf >= 0 && rpf <= 1.0) { pf = rpf; lpf = rpf; } else pf = lpf;
        }
    }
};

// --- 3.3 WiFi Manager ---
class WiFiManager : public Process {
  const char* TARGET_SSID = WIFI_SSID; 
  unsigned long lastInternetCheck = 0;
  unsigned long stateEntryTime = 0;
  unsigned long backoffEndTime = 0;
  unsigned long disconnectWaitStart = 0; 

  const unsigned long INTERNET_CHECK_INTERVAL = 60000; 
  int internetFailCount = 0;
  bool wifiInitDone = false; 

  enum WifiState { WF_BOOT, WF_OFFLINE, WF_CONNECTING, WF_CONNECTED, WF_BACKOFF, WF_DISCONNECTED, WF_AP_FALLBACK };
  WifiState currentState = WF_BOOT;

  public:
    void setup() override {
        Sys.log("[WiFi] Manager Ready");
        changeState(WF_OFFLINE);
    }

    void update() override {
        bool isProbation = (currentState == WF_CONNECTED && (millis() - stateEntryTime < 120000));

        switch (currentState) {
            case WF_OFFLINE:
                if (millis() - stateEntryTime > 30000) changeState(WF_CONNECTING);
                break;

            case WF_CONNECTING:
                if (!wifiInitDone) {
                    if (disconnectWaitStart == 0) {
                        Sys.log("📡 Init: Disconnecting...");
                        WiFi.mode(WIFI_STA); WiFi.disconnect(); 
                        disconnectWaitStart = millis(); return; 
                    }
                    if (millis() - disconnectWaitStart < 100) return;

                    Sys.log("📡 Init: Connecting to " + String(TARGET_SSID) + "...");
                    Sys.lastConnectAttempt = (Sys.rtcValid) ? rtc.now().timestamp(DateTime::TIMESTAMP_TIME) : String(millis()/1000);
                    WiFi.begin(WIFI_SSID, WIFI_PASS);
                    wifiInitDone = true; 
                }
                if (WiFi.status() == WL_CONNECTED) changeState(WF_CONNECTED);
                else if (millis() - stateEntryTime > 20000) { 
                    Sys.log("❌ Connect Timeout");
                    changeState(WF_BACKOFF); 
                }
                break;

            case WF_CONNECTED:
                if (WiFi.status() != WL_CONNECTED) {
                    Sys.log("❌ Signal Lost");
                    changeState(WF_DISCONNECTED);
                } else {
                    Sys.wifiRssi = WiFi.RSSI(); 
                    if (!isProbation) {
                        unsigned long interval = (Sys.internetAvailable) ? 60000 : INTERNET_CHECK_INTERVAL;
                        if (millis() - lastInternetCheck > interval + random(0, 10000)) {
                            checkConnectivity(); lastInternetCheck = millis();
                        }
                    }
                }
                break;

            case WF_DISCONNECTED:
                if (millis() - stateEntryTime > 2000) {
                    Sys.wifiConnected = false; Sys.internetAvailable = false;
                    changeState(WF_BACKOFF); 
                }
                break;

            case WF_BACKOFF:
                if (millis() > backoffEndTime) {
                    Sys.log("⏳ Backoff Expired");
                    changeState(WF_CONNECTING);
                }
                break;

            case WF_AP_FALLBACK:
                if (millis() - stateEntryTime > 300000) { 
                    Sys.log("🔄 Leaving AP Mode");
                    WiFi.softAPdisconnect(true); WiFi.mode(WIFI_STA); Sys.apMode = false;
                    changeState(WF_OFFLINE);
                }
                break;
            case WF_BOOT: changeState(WF_OFFLINE); break;
        }
    }

    void onStateChange(DeviceState newState) override {
        if (newState == DEVICE_ONLINE) lastInternetCheck = millis(); 
    }
    bool isHealthy() override { return true; } 
    String getName() override { return "WiFiMgr"; }

  private:
    void changeState(WifiState newState) {
        currentState = newState;
        stateEntryTime = millis();
        disconnectWaitStart = 0; 
        wifiInitDone = false; // <-- Added to fix the wifi not connecting issue

        switch(newState) {
            case WF_OFFLINE: Sys.wifiStateLabel = "OFFLINE"; break;
            case WF_CONNECTING: Sys.wifiStateLabel = "CONNECTING"; break;
            case WF_CONNECTED: Sys.wifiStateLabel = "ONLINE"; break;
            case WF_BACKOFF: Sys.wifiStateLabel = "BACKOFF (5m)"; break;
            case WF_AP_FALLBACK: Sys.wifiStateLabel = "AP MODE"; break;
            default: Sys.wifiStateLabel = "RETRY"; break;
        }

        switch (newState) {
            case WF_CONNECTED: 
                Sys.log("✅ Connected! IP: " + WiFi.localIP().toString());
                Sys.wifiConnected = true; Sys.radioDead = false; Sys.rebootRequired = false;
                internetFailCount = 0; Sys.internetAvailable = false; 
                if (Sys.apMode) { WiFi.softAPdisconnect(true); Sys.apMode = false; }
                break;
            case WF_BACKOFF:
                Sys.log("🛑 Entering BACKOFF");
                backoffEndTime = millis() + 300000;
                Sys.radioDead = false; Sys.rebootRequired = false;
                break;
            case WF_AP_FALLBACK:
                Sys.log("⚠️ AP Fallback");
                WiFi.mode(WIFI_AP_STA); WiFi.softAP("PowerOS_Offline", "12345678");
                Sys.apMode = true; Sys.wifiConnected = false; Sys.internetAvailable = false;
                Sys.radioDead = false; Sys.rebootRequired = false;
                break;
            case WF_DISCONNECTED:
            case WF_OFFLINE:
            case WF_CONNECTING:
                Sys.wifiConnected = false; Sys.internetAvailable = false;
                break;
        }
    }

    void checkConnectivity() {
        HTTPClient http; http.setTimeout(3000); 
        http.begin("http://clients3.google.com/generate_204"); 
        int code = http.GET(); http.end();
        if (code == 204) {
            internetFailCount = 0; 
            if (!Sys.internetAvailable) { Sys.log("🟢 Online + Internet"); Sys.internetRecovered = true; }
            Sys.internetAvailable = true; Sys.pingSuccess = true;
        } else {
            internetFailCount++;
            if (internetFailCount >= 2) { Sys.internetAvailable = false; Sys.pingSuccess = false; }
        }
    }
};

// --- 3.4 Data Manager ---
class DataManager : public Process {
  Preferences prefs;
  long lastB5 = -1, lastBH = -1, lastBD = -1;
  float lastE1 = 0.0, lastE2 = 0.0; 
  const int MAX_BUFFER_LINES = 2000;
  String deviceMac = ""; 

  bool syncPaused = false;
  unsigned long resumeTime = 0;
  int consecutiveUploadFails = 0;
  unsigned long lastStorageCheck = 0;

  const char* F_5M = "/buf_5m.txt"; const char* S_5M = "/stg_5m.txt";
  const char* F_1H = "/buf_1h.txt"; const char* S_1H = "/stg_1h.txt";
  const char* F_1D = "/buf_1d.txt"; const char* S_1D = "/stg_1d.txt";

  public:
    void setup() override {
        Sys.log("[Data] Mounting FS...");
        if (!LittleFS.begin(true)) Sys.log("❌ FS Mount Failed");
        deviceMac = WiFi.macAddress(); deviceMac.replace(":", "");
        recoverPipeline(S_5M, F_5M); recoverPipeline(S_1H, F_1H); recoverPipeline(S_1D, F_1D);
        updateTotalBufferCount();
        prefs.begin("buckets", false);
        lastB5 = prefs.getLong("b5", -1); lastBH = prefs.getLong("bh", -1); lastBD = prefs.getLong("bd", -1);
        lastE1 = prefs.getFloat("le1", 0.0); lastE2 = prefs.getFloat("le2", 0.0);
        prefs.end();
    }

    void update() override {
        checkBuckets(); runSyncEngine(); checkStorageHealth(); 
    }

    void onStateChange(DeviceState newState) override {
        if (newState == DEVICE_ONLINE) {
            syncPaused = false; resumeTime = 0; consecutiveUploadFails = 0; Sys.serviceLocked = false;
        }
    }

    void performFactoryReset() {
        Sys.log("🔥 Formatting..."); LittleFS.format();
        prefs.begin("buckets", false); prefs.clear(); prefs.end();
        Sys.bufferCount = 0; lastB5 = -1; lastBH = -1; lastBD = -1;
        Sys.log("✅ Reset Complete");
    }

    void checkStorageHealth() {
        if (millis() - lastStorageCheck > 600000) { 
            lastStorageCheck = millis();
            if (LittleFS.totalBytes() > 0) {
                if ((float)LittleFS.usedBytes() / (float)LittleFS.totalBytes() > 0.90) { 
                    Sys.log("🚨 STORAGE 90% -> PURGING");
                    LittleFS.remove(F_5M); LittleFS.remove(S_5M); updateTotalBufferCount();
                }
            }
        }
    }
    bool isHealthy() override { return true; }
    String getName() override { return "DataMgr"; }

  private:
    void runSyncEngine() {
        if (Sys.otaActive || Sys.deviceState != DEVICE_ONLINE || !Sys.internetAvailable) {
            Sys.isSyncing = false; Sys.syncStateLabel = "PAUSED"; return;
        }
        if (syncPaused) {
            Sys.syncStateLabel = "BACKOFF";
            if (millis() < resumeTime) return;
            syncPaused = false;
        }

        Sys.syncStateLabel = "ACTIVE";
        int processedCount = 0;
        unsigned long startBurst = millis();
        while (millis() - startBurst < 500 && processedCount < 5) {
            if (!processOneBatch()) break;
            processedCount++; yield(); 
        }
        Sys.isSyncing = (processedCount > 0);
    }

    bool processOneBatch() {

    const char* activeBuf = nullptr;
    const char* activeStg = nullptr;

    if (LittleFS.exists(S_5M) || fileHasData(F_5M)) {
        activeBuf = F_5M;
        activeStg = S_5M;
        Sys.batchName = "/stg_5m";
    }
    else if (LittleFS.exists(S_1H) || fileHasData(F_1H)) {
        activeBuf = F_1H;
        activeStg = S_1H;
        Sys.batchName = "/stg_1h";
    }
    else if (LittleFS.exists(S_1D) || fileHasData(F_1D)) {
        activeBuf = F_1D;
        activeStg = S_1D;
        Sys.batchName = "/stg_1d";
    }
    else {
        Sys.batchName = "Empty";
        return false;
    }

    // Promote buffer to staging if required
    if (!LittleFS.exists(activeStg)) {
        if (fileHasData(activeBuf)) {
            if (!LittleFS.rename(activeBuf, activeStg))
                return false;

            Sys.log("🔄 Sync: Batch (" + String(activeStg) + ")");
        }
        else {
            return false;
        }
    }

    File f = LittleFS.open(activeStg, "r");
    if (!f) {
        LittleFS.remove(activeStg);
        return false;
    }

    // Read first 50 records
    const int MAX_BATCH = 50;
    String lines[MAX_BATCH];
    int lineCount = 0;

    while (f.available() && lineCount < MAX_BATCH) {
        lines[lineCount] = f.readStringUntil('\n');
        lines[lineCount].trim();

        if (lines[lineCount].length() > 10)
            lineCount++;
    }

    int successCount = 0;

    // Upload records
    for (int i = 0; i < lineCount; i++) {

        if (sendToCloud(lines[i])) {

            successCount++;

            if (Sys.bufferCount > 0)
                Sys.bufferCount--;

        } else {
            break;
        }
        esp_task_wdt_reset();
        yield();   // keep WiFi alive
    }

    // Nothing uploaded
    if (successCount == 0) {

        f.close();

        consecutiveUploadFails++;

        if (consecutiveUploadFails >= 3) {
            syncPaused = true;
            resumeTime = millis() + 30000;
            Sys.log("⚠️ Upload Fail -> Pausing");
        }

        if (consecutiveUploadFails >= 10)
            Sys.serviceLocked = true;

        return false;
    }

    // Rewrite remaining records only once
    String tempName = "/temp_sync.txt";
    File fNew = LittleFS.open(tempName, "w");

    // Otherwise, if LittleFS ever fails to create the temp file, you'll continue writing to an invalid handle.
    if (!fNew) {
    f.close();
    return false;
}

    // Skip already processed records that are still in file
    for (int i = successCount; i < lineCount; i++) {
        fNew.println(lines[i]);
    }

    // Copy remainder of file
    while (f.available()) {
        fNew.write(f.read());
    }

    f.close();
    fNew.close();

    LittleFS.remove(activeStg);
    LittleFS.rename(tempName, activeStg);

    updateTotalBufferCount();

    consecutiveUploadFails = 0;
    Sys.serviceLocked = false;

    if (!fileHasData(activeStg)) {
        LittleFS.remove(activeStg);
        updateTotalBufferCount();
        Sys.log("✅ Batch Complete");
    }

    return true;
}

    bool sendToCloud(String payload) {
        WiFiClientSecure client; client.setInsecure(); HTTPClient http;
        String url = DB_URL;
        if (payload.endsWith("|H")) { url.replace("power_logs", "hourly_logs"); payload.remove(payload.length()-2); }
        else if (payload.endsWith("|D")) { url.replace("power_logs", "daily_logs"); payload.remove(payload.length()-2); }
        if (url.indexOf("?auth=") == -1) url += "?auth=" + String(DB_SECRET);

        http.setReuse(false); http.setTimeout(6000); 
        if (http.begin(client, url)) {
            http.addHeader("Content-Type", "application/json");
            int code = http.POST(payload); http.end();
            Sys.lastHttpCode = code;

            if (code >= 200 && code < 300) { 
                Sys.syncSuccessCount++; 
                if(Sys.rtcValid) Sys.lastSyncTime = rtc.now().timestamp(DateTime::TIMESTAMP_TIME);
                return true; 
            }
            Sys.syncFailCount++;
            if (code == 400) { Sys.log("🗑️ HTTP 400"); return true; }
        } else {
            Sys.syncFailCount++; Sys.lastHttpCode = -1;
        }
        return false;
    }

    String getUuid(long epoch) { return deviceMac + "_" + String(epoch); }
    // [FIX] HTTP 400 SANITIZER + PHANTOM GUARD
    // 1. Converts NaN to 0.0 (Fixes HTTP 400 Error during sensor glitches)
    // 2. Forces 0.0 if Voltage < 150V (Fixes Phantom/Ghost readings)
    String buildJson(String ts, long epoch, int type) {
        char buffer[300];

        // --- SENSOR 1 (GRID) ---
        // Step A: Sanitize NaN
        float safe_v1 = isnan(Sys.v1) ? 0.0 : Sys.v1;
        float safe_i1 = isnan(Sys.i1) ? 0.0 : Sys.i1;
        float safe_w1 = isnan(Sys.w1) ? 0.0 : Sys.w1;
        float safe_e1 = isnan(Sys.e1) ? 0.0 : Sys.e1;

        // Step B: Phantom Voltage Guard (<150V = 0)
        if (safe_v1 < 150.0) { safe_v1 = 0; safe_i1 = 0; safe_w1 = 0; }

        // --- SENSOR 2 (INVERTER) ---
        // Step A: Sanitize NaN
        float safe_v2 = isnan(Sys.v2) ? 0.0 : Sys.v2;
        float safe_i2 = isnan(Sys.i2) ? 0.0 : Sys.i2;
        float safe_w2 = isnan(Sys.w2) ? 0.0 : Sys.w2;
        float safe_e2 = isnan(Sys.e2) ? 0.0 : Sys.e2;

        // Step B: Phantom Voltage Guard (<150V = 0)
        if (safe_v2 < 150.0) { safe_v2 = 0; safe_i2 = 0; safe_w2 = 0; }

        snprintf(buffer, sizeof(buffer), 
            "{\"id\":\"%s\",\"timestamp\":\"%s\",\"v1\":%.1f,\"i1\":%.2f,\"w1\":%.0f,\"e1\":%.2f,\"v2\":%.1f,\"i2\":%.2f,\"w2\":%.0f,\"e2\":%.2f}",
            getUuid(epoch).c_str(), ts.c_str(), 
            safe_v1, safe_i1, safe_w1, safe_e1,
            safe_v2, safe_i2, safe_w2, safe_e2
        );
        return String(buffer);
    }

    void saveBucket(const char* k, long v) {
        if (prefs.getLong(k, -1) != v) { prefs.begin("buckets", false); prefs.putLong(k, v); prefs.end(); }
    }
    void saveSnapshot(float e1, float e2) {
        prefs.begin("buckets", false); prefs.putFloat("le1", e1); prefs.putFloat("le2", e2); prefs.end();
    }
    bool fileHasData(const char* fn) {
        if(!LittleFS.exists(fn)) return false; File f = LittleFS.open(fn, "r");
        bool hasData = (f.size() > 0); f.close(); return hasData;
    }
    int countLines(const char* fn) {
        if(!LittleFS.exists(fn)) return 0; File f = LittleFS.open(fn, "r");
        int c=0; while(f.available()) { if(f.read()=='\n') c++; if (c % 10 == 0) esp_task_wdt_reset(); }
        f.close(); return c;
    }
    void recoverPipeline(const char* stage, const char* buffer) {
        if (!LittleFS.exists(stage)) return;
        File fStg = LittleFS.open(stage, "r"); File fBuf = LittleFS.open(buffer, FILE_APPEND);
        while(fStg.available()) {
            esp_task_wdt_reset(); String line = fStg.readStringUntil('\n'); line.trim();
            if(line.length() > 10) fBuf.println(line);
        }
        fStg.close(); fBuf.close(); LittleFS.remove(stage);
    }
    void updateTotalBufferCount() { Sys.bufferCount = countLines(F_5M) + countLines(F_1H) + countLines(F_1D); }

    void checkBuckets() {
        if (!Sys.rtcValid) return; DateTime now = rtc.now(); long currentEpoch = now.unixtime();
        long interval5m = 300; long b5 = currentEpoch / interval5m;
        if (lastB5 != -1 && b5 > lastB5) {
            long alignedEpoch = b5 * interval5m; DateTime dt(alignedEpoch);
            if (dispatch(buildJson(dt.timestamp(), alignedEpoch, 0), 0)) { saveBucket("b5", b5); lastB5 = b5; }
        } else if (lastB5 == -1) lastB5 = b5;

        long interval1h = 3600; long bh = currentEpoch / interval1h;
        if (lastBH != -1 && bh > lastBH) {
            long alignedEpoch = bh * interval1h; DateTime dt(alignedEpoch);
            if (dispatch(buildJson(dt.timestamp(), alignedEpoch, 1) + "|H", 1)) { saveBucket("bh", bh); lastBH = bh; }
        } else if (lastBH == -1) lastBH = bh;

        long interval1d = 86400; long bd = currentEpoch / interval1d;
        if (lastBD != -1 && bd > lastBD) {
            DateTime yesterday = now - TimeSpan(1, 0, 0, 0);
            float consumed1 = (Sys.e1 - lastE1 < 0) ? 0 : Sys.e1 - lastE1;
            float consumed2 = (Sys.e2 - lastE2 < 0) ? 0 : Sys.e2 - lastE2;
            DateTime yMidnight(yesterday.year(), yesterday.month(), yesterday.day(), 0, 0, 0);
            long yEpoch = yMidnight.unixtime(); char tb[30]; 
            snprintf(tb, 30, "%04d-%02d-%02dT00:00:00", yesterday.year(), yesterday.month(), yesterday.day());
            String dJson = "{\"id\":\""+getUuid(yEpoch)+"\",\"timestamp\":\""+String(tb)+"\",\"e1\":"+String(consumed1)+",\"e2\":"+String(consumed2)+"}";
            if (dispatch(dJson + "|D", 2)) {
                saveBucket("bd", bd); lastBD = bd; lastE1 = Sys.e1; lastE2 = Sys.e2; saveSnapshot(lastE1, lastE2);
            }
        } else if (lastBD == -1) { lastBD = bd; lastE1 = Sys.e1; lastE2 = Sys.e2; saveSnapshot(lastE1, lastE2); }
    }

    bool dispatch(String payload, int type) {
        if (Sys.isSyncing || Sys.otaActive || Sys.deviceState != DEVICE_ONLINE) return bufferToPipeline(payload, type);
        bool success = sendToCloud(payload);
        if (!success) {
            if(bufferToPipeline(payload, type)) { if(type==0) Sys.log("⚠️ Live Buffered"); return true; } else return false; 
        } else {
            if(type==0) Sys.log("✅ Upload Success"); return true;
        }
    }
    bool bufferToPipeline(String line, int type) {
        if (Sys.bufferCount >= MAX_BUFFER_LINES) { Sys.log("❌ Buffer Full"); return false; }
        File f = LittleFS.open((type==1)?F_1H:((type==2)?F_1D:F_5M), FILE_APPEND);
        if (f) { f.println(line); f.close(); Sys.bufferCount++; return true; }
        return false;
    }
};

