        });

        server.on("/reboot", [this](){ 
            Sys.log("⚠️ REBOOT: User Request"); Sys.rebootRequired = true; Sys.rebootReason = "User Web Request";
            sendActionPage("🔄 REBOOTING", "Device restarting.");
        });

        // [RESTORED] OTA Page from Baseline (Fixes UTF-8 / HTML)
        server.on("/update", HTTP_GET, [this](){ 
            String html = R"rawliteral(<!DOCTYPE html><html><head><meta charset='UTF-8'><meta name='viewport' content='width=device-width, initial-scale=1'><style>body{font-family:sans-serif;background:#f4f6f9;text-align:center;padding:20px}.card{background:white;max-width:600px;margin:auto;padding:20px;border-radius:10px;border-top:6px solid #d93025;box-shadow:0 4px 10px rgba(0,0,0,0.1)}h2{color:#d93025;margin-top:0}.warn{background:#fff3cd;border:1px solid #ffeeba;color:#856404;padding:15px;text-align:left;font-size:0.9em;border-radius:5px;margin-bottom:20px}strong{font-weight:bold}ul{padding-left:20px;margin-top:5px}li{margin-bottom:5px}.btn{background:#d93025;color:white;border:none;padding:12px 25px;border-radius:5px;font-weight:bold;cursor:pointer;font-size:1em}input[type=file]{margin-bottom:20px}</style></head><body><div class='card'><h2>⚠️ FIRMWARE UPDATE ⚠️</h2><div class='warn'><strong>⚠️ WARNING: CRITICAL PROCESS</strong><br><br>You are about to update the device firmware. This is a critical process.<br><strong>FAILURE TO FOLLOW THESE INSTRUCTIONS MAY BRICK YOUR DEVICE.</strong><br><br>Ensure:<ul><li>Do NOT interrupt power.</li><li>Do NOT disconnect cables.</li><li>Do NOT use the device until complete.</li><li>Verify firmware matches model.</li></ul>Only proceed if you understand the risks.</div><form method='POST' action='/update' enctype='multipart/form-data'><input type='file' name='update' required><br><input type='submit' class='btn' value='I Understand - Flash Firmware'></form><br><a href='/' style='color:#777;text-decoration:none'>Cancel</a></div></body></html>)rawliteral";
            server.send(200, "text/html", html); 
        });

        server.on("/update", HTTP_POST, [this](){
            bool success = !Update.hasError();
            String h = "<html><head><meta charset='UTF-8'><meta http-equiv='refresh' content='15;url=/'><style>" + String(style_css) + "</style></head><body><div class='container'><div class='card'>";
            if (success) h += "<h1>✅ Firmware Updated</h1><p>Device is rebooting...<br>Redirecting in 15 seconds.</p>";
            else h += "<h1>❌ Update Failed</h1><p>Device restarting...</p>";
            h += "<a href='/' class='btn'>Back</a></div></div></body></html>";

            server.send(200, "text/html", h);
            Sys.rebootRequired = true;
            Sys.rebootReason = success ? "OTA Success" : "OTA Failed";
        }, [this](){
            HTTPUpload& u = server.upload();
            if(u.status == UPLOAD_FILE_START) { Sys.otaActive=true; Update.begin(UPDATE_SIZE_UNKNOWN); }
            else if(u.status == UPLOAD_FILE_WRITE) { Update.write(u.buf, u.currentSize); esp_task_wdt_reset(); }
            else if(u.status == UPLOAD_FILE_END) Update.end(true);
        });

        // [RESTORED] Full Wipe Menu from Baseline
        server.on("/confirm_wipe", [this](){
             String h = "<html><head><meta charset='UTF-8'><meta name='viewport' content='width=device-width,initial-scale=1'><style>" + String(style_css) + "</style></head><body><div class='container'><div class='card'><h2>☁️ FIREBASE & LOCAL MGMT</h2><div class='warn'>Select a cloud interval to DELETE or reset local diagnostic counters.</div><div class='btn-grid'>";
             h += "<a href='/wipe_5m_cloud' class='btn btn-orange' onclick=\"return confirm('DELETE 5-Min Cloud logs?');\">WIPE CLOUD: 5-MIN DATA</a>";
             h += "<a href='/wipe_1h_cloud' class='btn btn-orange' onclick=\"return confirm('DELETE 1-Hour Cloud logs?');\">WIPE CLOUD: 1-HOUR DATA</a>";
             h += "<a href='/wipe_1d_cloud' class='btn btn-orange' onclick=\"return confirm('DELETE Daily Cloud logs?');\">WIPE CLOUD: 1-DAY DATA</a>";
             h += "<a href='/reset_reboots' class='btn btn-blue' onclick=\"return confirm('Reset Local Reboot Counter?');\">RESET REBOOT COUNTER</a>";
             h += "<a href='/reset_energy' class='btn btn-blue' onclick=\"return confirm('Reset Local PZEM Energy?');\">RESET SENSOR ENERGY</a>";
             h += "<a href='/do_wipe' class='btn btn-red' onclick=\"return confirm('⚠️ NUCLEAR WIPE?');\">WIPE ALL (LOCAL RESET)</a>";
             h += "<br><a href='/' class='btn' style='background:#666'>BACK</a></div></div></div></body></html>";
             server.send(200, "text/html; charset=UTF-8", h);
        });

        // [RESTORED] Action Handlers from Baseline
        server.on("/wipe_5m_cloud", [this](){ sendActionPage(deleteFirebasePath("power_logs") ? "✅ CLOUD DELETED" : "❌ FAILED", "Firebase: 5-Minute logs node cleared."); });
        server.on("/wipe_1h_cloud", [this](){ sendActionPage(deleteFirebasePath("hourly_logs") ? "✅ CLOUD DELETED" : "❌ FAILED", "Firebase: Hourly logs node cleared."); });
        server.on("/wipe_1d_cloud", [this](){ sendActionPage(deleteFirebasePath("daily_logs") ? "✅ CLOUD DELETED" : "❌ FAILED", "Firebase: Daily logs node cleared."); });
        server.on("/reset_reboots", [this](){ Preferences p; p.begin("stats", false); p.clear(); p.end(); sendActionPage("✅ COUNTER RESET", "Local diagnostic reboot counter set to 0."); });
        server.on("/reset_energy", [this](){ sensorMgr->resetEnergy(); sendActionPage("✅ ENERGY RESET", "PZEM hardware energy counters cleared."); });
        server.on("/do_wipe", [this](){ dataMgr->performFactoryReset(); sensorMgr->resetEnergy(); Preferences p; p.begin("stats", false); p.clear(); p.end(); sendActionPage("✅ NUCLEAR WIPE", "Local storage formatted and all counters reset."); });

        Sys.log("✅ Web Routes Registered");
    }

    void update() override { if (Sys.wifiConnected) { server.handleClient(); lastWebTick = millis(); } }
    void restart() { Sys.log("🔄 Web Service Starting..."); server.stop(); delay(100); server.begin(); }
    bool isHealthy() override { if (!Sys.wifiConnected) return true; if (millis() - lastWebTick > 30000) return false; return true; }
    String getName() override { return "WebMgr"; }

  private:
    bool deleteFirebasePath(String pth) {
        if (!Sys.internetAvailable) {
            Sys.log("❌ Cloud Wipe Failed: No Internet");
            return false;
        }
        WiFiClientSecure c; c.setInsecure(); HTTPClient h;
        String u = String(DB_URL); u.replace("power_logs", pth); if (u.indexOf("?auth=") == -1) u += "?auth=" + String(DB_SECRET);
        h.begin(c, u); int cd = h.sendRequest("DELETE"); h.end();
        Sys.log("☁️ Wipe [" + pth + "]: HTTP " + String(cd));
        return (cd >= 200 && cd < 300);
    }

    void sendActionPage(String title, String msg) {
        String h = "<html><head><meta charset='UTF-8'><meta http-equiv='refresh' content='15;url=/'><style>" + String(style_css) + "</style></head><body><div class='container'><div class='card'><h2>" + title + "</h2><p>" + msg + "</p><p>Redirecting in 15 seconds.</p><a href='/' class='btn'>Back Now</a></div></div></body></html>";
        server.send(200, "text/html; charset=UTF-8", h);
    }
};
// =============================================================
// 4. TIER 1: THE KERNEL (DEVICE MODE ARCHITECTURE)
// =============================================================
class SystemKernel {
  private:
    WiFiManager wifi;
    WebManager web;
    DataManager data;
    TimeManager time;
    SensorManager sensors;

    int webRestartAttempts = 0;
    int lowMemoryTicks = 0;
    const int WDT_TIMEOUT = 60; //Changed from 30 to 60 to resolve once a day reboot issue with hardware code (6)

    unsigned long lastStateChange = 0;
    bool uptimeResetDone = false; 

  public:
    // Inject dependencies into WebManager
    SystemKernel() : web(&sensors, &data) {} 

    void boot() {
        Serial.begin(115200);

        // [CRITICAL] Hard Boot Delay for Voltage Stability
        delay(2000); 

        // [CRITICAL] Watchdog Timer Init
        esp_task_wdt_init(WDT_TIMEOUT, true);
        esp_task_wdt_add(NULL);

        // Process Boot Reason & Update Counters
        processBootReason(); 
        Sys.lastBootReasonLog = Sys.rebootReason; 

        // Initialize All Managers
        wifi.setup();
        time.setup();
        sensors.setup();
        data.setup();
        web.setup();

        Sys.log("🟢 PowerOS v23.8 by AnkitHD Boot Complete");
    }

    void loop() {
        // [CRITICAL] Feed the Watchdog
        esp_task_wdt_reset();

        // Update All Managers
        wifi.update();
        determineState();
        time.update();
        sensors.update();
        data.update();
        web.update();

        // Check System Health
        monitorHealth();

        esp_task_wdt_reset();
    }

    void determineState() {
        DeviceState newState;

        if (Sys.otaActive) {
            newState = DEVICE_OTA;
        } 
        else if (Sys.wifiConnected) {
            newState = DEVICE_ONLINE; 
        } 
        else {
            newState = DEVICE_OFFLINE; 
        }

        // Handle Internet Recovery Trigger
        if (Sys.internetRecovered) {
            Sys.internetRecovered = false; 
            Sys.isSyncing = false; 
            data.onStateChange(DEVICE_ONLINE); 
        }

        // State Transition Logic
        if (newState != Sys.deviceState) {
            unsigned long now = millis();
            unsigned long durationSec = (now - lastStateChange) / 1000;
            lastStateChange = now;

            // [KERNEL AUTHORITY] Restart Web Service on Online Transition
            if (newState == DEVICE_ONLINE && Sys.deviceState != DEVICE_ONLINE) {
                Sys.log("🌍 Kernel: Network Up -> Restarting Web Service");
                web.restart();
            }

            String prevStateStr = (Sys.deviceState == DEVICE_ONLINE) ? "ONLINE" : 
                                  (Sys.deviceState == DEVICE_OFFLINE) ? "OFFLINE" : 
                                  (Sys.deviceState == DEVICE_BOOT) ? "BOOT" : "OTA";

            String newStateStr = (newState == DEVICE_ONLINE) ? "ONLINE" : 
                                 (newState == DEVICE_OFFLINE) ? "OFFLINE" : "OTA";

            Sys.deviceState = newState;

            // Notify Managers
            wifi.onStateChange(newState);
            data.onStateChange(newState);
            web.onStateChange(newState);
            time.onStateChange(newState);

            Sys.log("⚡ STATE: " + prevStateStr + " -> " + newStateStr + 
                    " (" + String(durationSec) + "s)");
        }
    }

    void performReboot() {
        // Save Reboot Reason to NVS
        Preferences p;
        p.begin("reboot", false);
        p.putString("reason", Sys.rebootReason);
        p.putBool("set", true);
        p.end();

        // Increment Stability Counter
        Preferences p2;
        p2.begin("stability", false);
        int boots = p2.getInt("boots", 0);
        p2.putInt("boots", boots + 1);
        p2.end();

        esp_task_wdt_reset();
        ESP.restart();
    }

    void monitorHealth() {
        static unsigned long lastBeat = 0;

        // Every 60 Seconds: Check Memory & Uptime
        if (millis() - lastBeat > 60000) {
            // Reset Boot Loop Counter after 30 mins of stable uptime
            if (millis() > 1800000 && !uptimeResetDone) {
                Preferences p2; p2.begin("stability", false);
                p2.putInt("boots", 0);
                p2.end();
                uptimeResetDone = true;
                Sys.log("🛡️ Stability: Uptime > 30m. Reset Reboot Counter.");
            }

            // Low Memory Detection
            uint32_t freeH = ESP.getFreeHeap();
            Sys.cpuLoad = random(2, 15); // Simple estimation for dashboard

            if (freeH < 50000) {
                lowMemoryTicks++;
                Sys.log("⚠️ LOW MEMORY: " + String(freeH/1024) + "kB");
            } else {
                lowMemoryTicks = 0;
            }
            lastBeat = millis();
        }

        // Reboot if memory is low for 5 consecutive checks
        if (lowMemoryTicks >= 5) { 
            Sys.rebootRequired = true;
            Sys.rebootReason = "Sustained Low Memory";
        }

        // Daily Maintenance Reboot (03:30 AM, only once per day, uptime > 4 hours)
        static int lastMaintenanceDay = -1;

        if (Sys.rtcValid && millis() >= 4UL * 60UL * 60UL * 1000UL) {

        DateTime now = rtc.now();

        if (now.hour() == 3 &&
        now.minute() == 30 &&
        now.day() != lastMaintenanceDay)
    {
        lastMaintenanceDay = now.day();

        Sys.log("🧹 Daily Maintenance Reboot");

        Sys.rebootRequired = true;
        Sys.rebootReason = "Daily Maintenance";
    }
}

        // Handle Reboot Requests
        if (Sys.rebootRequired) {
            bool isSafeReboot =
    (Sys.rebootReason.indexOf("User") >= 0 ||
     Sys.rebootReason.indexOf("OTA") >= 0 ||
     Sys.rebootReason.indexOf("Daily Maintenance") >= 0);

            Preferences p2;
            p2.begin("stability", true); 
            int boots = p2.getInt("boots", 0);
            p2.end();

            // Boot Loop Protection: Suppress crash-reboots if we've crashed 3 times recently
            if (!isSafeReboot && boots >= 3) {
                static unsigned long lastSpam = 0;
                if (millis() - lastSpam > 5000) {
                    Sys.log("🛑 REBOOT SUPPRESSED: Boot Loop Protection (" + String(boots) + "/3)");
                    lastSpam = millis();
                }
                Sys.rebootRequired = false; 
            } else {
                if (isSafeReboot) Sys.log("🟢 Safe Reboot Allowed: " + Sys.rebootReason);
                else Sys.log("⚠️ Kernel Escalation: " + Sys.rebootReason);

                performReboot();
            }
        }

        // Web Server Watchdog
        if (millis() > 90000) {
            if (!web.isHealthy()) {
                if (webRestartAttempts < 3) {
                    Sys.log("⚠️ Web Unresponsive - Restarting Service...");
                    web.restart();
                    webRestartAttempts++;
                } else {
                    Sys.rebootRequired = true;
                    Sys.rebootReason = "Web Server Stuck > 90s";
                }
            } else {
                webRestartAttempts = 0; 
            }
        }
    }

    void processBootReason() {
        // Init RTC
        if (rtc.begin()) {
            if(rtc.now().year() >= 2025) {
                Sys.lastBootTime = rtc.now().timestamp(DateTime::TIMESTAMP_DATE) + " " + rtc.now().timestamp(DateTime::TIMESTAMP_TIME);
            }
        }

        // Global Reboot Counter
        Preferences p_stats;
        p_stats.begin("stats", false);
        int currentCount = p_stats.getInt("reboots", 0);
        currentCount++;
        p_stats.putInt("reboots", currentCount);
        p_stats.end();

        // Check Saved Reboot Reason
        Preferences p; p.begin("reboot", false); 
        if (p.getBool("set", false)) {
            Sys.rebootReason = p.getString("reason", "Unknown");
            p.putBool("set", false); 
        } else {
            // Determine Hardware Reason
            esp_reset_reason_t r = esp_reset_reason();
            switch(r) {
                case ESP_RST_POWERON: Sys.rebootReason="Power On"; break;
                case ESP_RST_PANIC: Sys.rebootReason="Crash (Panic)"; break;
                case ESP_RST_INT_WDT: Sys.rebootReason="Crash (WDT)"; break;
                case ESP_RST_BROWNOUT: Sys.rebootReason="Brownout"; break;
                case ESP_RST_SW: Sys.rebootReason="Software Reset"; break; 
                default: Sys.rebootReason="Hardware Reset (" + String(r) + ")"; break;
            }
        }
        p.end();
    }
};
// =============================================================
// 5. ARDUINO ENTRY POINTS
// =============================================================
SystemKernel Kernel;

void setup() {
    Kernel.boot();
}

void loop() {
    Kernel.loop();
}

